const apiBase='/api';
function formDataObject(form){return Object.fromEntries(new FormData(form).entries())}
async function post(path,data){const r=await fetch(`${apiBase}/${path}`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)});const j=await r.json().catch(()=>null);if(!j)throw new Error('Invalid server response');return j}
function esc(v){return String(v??'').replace(/[&<>"']/g,s=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[s]))}
const flightForm=document.querySelector('#flightForm');
if(flightForm)flightForm.addEventListener('submit',async e=>{e.preventDefault();const s=document.querySelector('#flightStatus'),r=document.querySelector('#flightResults');s.textContent='جاري البحث في Travelport…';r.innerHTML='';try{const j=await post('flight-search',formDataObject(flightForm));if(j.mode==='setup'){s.innerHTML='<b>'+esc(j.message||'محرك الطيران يحتاج بيانات Travelport في Cloudflare.')+'</b>';return}if(j.mode!=='live'){s.innerHTML='<b>تعذر البحث.</b> '+esc(j.message||'');return}s.textContent='تم استلام نتائج حقيقية من Travelport';r.innerHTML='<article class=\"gb-card\"><div><h3>نتائج Travelport وصلت بنجاح</h3><p>تم استلام بيانات البحث من بيئة الاختبار. سيتم إضافة بطاقات الرحلات التفصيلية والتسعير AirPrice في الخطوة التالية.</p></div><div><small>لا يتم عرض سعر غير مؤكد.</small></div></article>';window.__lastTravelportResults=j.results;}catch(err){s.textContent='حدث خطأ أثناء الاتصال بمحرك الطيران.';console.error(err)}});
const hotelForm=document.querySelector('#hotelForm');
if(hotelForm)hotelForm.addEventListener('submit',async e=>{e.preventDefault();const s=document.querySelector('#hotelStatus'),r=document.querySelector('#hotelResults');s.textContent='جاري البحث عن التوافر الحقيقي…';r.innerHTML='';try{const d=formDataObject(hotelForm);d.location=d.cityCode;const j=await post('hotel-search',d);if(j.mode==='setup'){s.innerHTML='<b>محرك الفنادق جاهز.</b> يلزم وضع FX-Port Sandbox API Key داخل Cloudflare Worker Secret.';return}if(j.mode!=='live'){s.innerHTML=`<b>تعذر البحث.</b> ${esc(j.message||'')}`;return}const results=Array.isArray(j.results)?j.results:[];s.textContent=`FX-Port: تم العثور على ${results.length} نتيجة متاحة`;r.innerHTML=results.map(x=>`<article class="gb-card"><div>${x.image?`<img src="${esc(x.image)}" alt="${esc(x.name||'Hotel')}" loading="lazy" style="width:110px;height:80px;object-fit:cover;border-radius:12px">`:''}</div><div><h3>${esc(x.name||'Hotel')}</h3><p>${esc(x.destination||d.cityCode||'')} ${x.stars?`· ${esc(x.stars)}★`:''}</p><p>${x.available===false?'غير متاح':'متاح مبدئيًا'}${x.room?` · ${esc(x.room)}`:''}${x.meal?` · ${esc(x.meal)}`:''}</p><small>السعر والتوافر النهائيان يُؤكَّدان قبل إتمام الحجز.</small></div><div><button class="btn primary" type="button" data-hotel-id="${esc(x.id||'')}">عرض الغرف</button></div></article>`).join('')||'<p>لم يتم العثور على فنادق مطابقة لهذه البيانات.</p>';r.querySelectorAll('[data-hotel-id]').forEach(btn=>btn.addEventListener('click',async()=>{const hotelId=btn.dataset.hotelId;const j2=await post('hotel-rooms',{hotelId,checkIn:d.checkIn,checkOut:d.checkOut,adults:d.adults,children:d.children||0});if(j2.mode==='live'){const data=j2.data||{};alert('تم جلب بيانات الغرف من FX-Port. راجع التفاصيل في نتيجة الفندق.');console.log('FX-Port rooms',data)}else alert(j2.message||'تعذر جلب الغرف.')}) )}catch(err){s.textContent='حدث خطأ أثناء الاتصال بمحرك الفنادق.';console.error(err)}});
const packageForm=document.querySelector('#packageForm');if(packageForm)packageForm.addEventListener('submit',async e=>{e.preventDefault();const s=document.querySelector('#packageStatus');try{const j=await post('trip-request',formDataObject(packageForm));s.textContent=`تم تسجيل طلبك برقم ${j.reference||'JSM'}. سيتواصل معك فريق JSM TRAVEL.`;packageForm.reset()}catch(err){s.textContent='تعذر تسجيل الطلب.'}});
